/* QuickSight 84bbd707-09dc-4b76-9e1c-ff4002cb85cb */
SELECT "bill_billing_period_start_date", "bill_payer_account_id", "line_item_usage_account_id", "charge_type", "product_product_name", "product_region", "line_item_product_code", "unblended_cost", "amortized_cost", "account_name", "payer_account_name", "region_latitude", "region_longitude", "aws_service_category"
FROM "cid_cur"."monthly_bill_by_account"

/* cppi::b2143e7441fc4a45ffcf0d4dc5d3f702265a8ad4df9947a2be45a444bb58b356 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-04-01'
    ) a
where last_publish = max_publish

